module.exports = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Mavis — one team, one platform</title>\n<meta name=\"description\" content=\"One connected platform for running a hospitality venue.\"><link rel=\"icon\" type=\"image/png\" href=\"/brand/mavis-favicon-v6.png\"><meta name=\"robots\" content=\"noindex\"><meta property=\"og:title\" content=\"Mavis — one team, one platform\"><meta property=\"og:description\" content=\"Early access is open. Places are limited.\"><meta property=\"og:image\" content=\"https://getmavis.vercel.app/brand/mavis-icon-1080.png?v=6\"><meta property=\"og:type\" content=\"website\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--navy:#0F1E2E;--teal:#0D9488;--teal-l:#2DD4BF;--gold:#C4973B;\n--paper:#F6F6F3;--card:#FFFFFF;--ink:#0F1E2E;--muted:#55606F;--line:#E2E6EC;--tile:#E3F3F1;--tile-ink:#0B7A70;\nbox-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--paper:#101C29;--card:#16263A;--ink:#EEF2F6;--muted:#9AA8B8;--line:#24364A;--tile:#143A3A;--tile-ink:#5EEAD4}}\n:root[data-theme=\"dark\"]{--paper:#101C29;--card:#16263A;--ink:#EEF2F6;--muted:#9AA8B8;--line:#24364A;--tile:#143A3A;--tile-ink:#5EEAD4}\nhtml{scroll-behavior:smooth;scroll-padding-top:calc(env(safe-area-inset-top,0px) + 64px)}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n*{box-sizing:border-box}\nbody{margin:0;font-family:Inter,system-ui,-apple-system,\"Segoe UI\",sans-serif;background:var(--paper);color:var(--ink);-webkit-font-smoothing:antialiased;overflow-x:hidden}\nimg{max-width:100%;height:auto;display:block}\na{color:inherit}\n:focus-visible{outline:3px solid var(--teal-l);outline-offset:3px;border-radius:6px}\n.wrap{max-width:1080px;margin:0 auto;padding:0 22px}\n/* top bar */\n.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:10;background:rgba(15,30,46,.92);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);color:#fff}\n.bar .wrap{display:flex;align-items:center;justify-content:space-between;height:58px}\n.logo img{height:32px;margin-left:-8px;width:auto;display:block}.foot img{height:24px;width:auto;display:inline-block;vertical-align:middle;margin-right:12px}.logo{font-weight:800;font-size:22px;letter-spacing:-.5px;text-decoration:none} .logo i{font-style:normal;color:var(--gold)}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 20px;border-radius:999px;font-weight:700;font-size:15px;text-decoration:none;border:0;cursor:pointer}\n.btn svg{width:18px;height:18px}\n.btn.wa{background:var(--teal);color:#fff} .btn.wa:hover{background:#0b8077}\n.btn.ghost{background:transparent;color:#fff;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.35)}\n.btn.ghost:hover{box-shadow:inset 0 0 0 1.5px #fff}\n.bar .btn{min-height:40px;padding:0 16px;font-size:14px}\n/* hero */\n.hero{background:linear-gradient(165deg,#0F1E2E 0%,#0F1F2E 38%,#112D32 62%,#11544D 88%,#106D64 100%);color:#fff;padding:56px 0 64px}\n.tag{display:inline-block;color:var(--gold);font-weight:700;font-size:13px;letter-spacing:.06em;border:1px solid rgba(196,151,59,.55);background:rgba(196,151,59,.09);border-radius:999px;padding:7px 14px}\n.hero h1{font-size:clamp(64px,19vw,148px);line-height:.92;letter-spacing:-.045em;font-weight:900;margin:22px 0 18px}\n.hero .lim{font-size:clamp(22px,5.6vw,34px);font-weight:800;color:var(--teal-l);letter-spacing:-.02em;margin:0 0 18px}\n.hero .offer{font-size:17px;line-height:1.6;color:rgba(255,255,255,.8);max-width:34em;margin:0 0 28px}\n.hero .offer b{color:#fff}\n.cta{display:flex;flex-wrap:wrap;gap:12px}\n.intro{margin-top:44px;padding-top:22px;border-top:1px solid rgba(255,255,255,.14);display:grid;gap:6px;max-width:36em}\n.intro strong{font-size:18px} .intro span{color:rgba(255,255,255,.65);line-height:1.6}\n.heroph{display:none}\n@media (min-width:900px){.hgrid{display:grid;grid-template-columns:1fr 330px;gap:56px;align-items:center}.heroph{display:block;width:320px}}\n/* why */\n.why{padding:64px 0 24px}\n.why h2{font-size:clamp(40px,10vw,72px);line-height:.98;letter-spacing:-.035em;font-weight:900;margin:0 0 14px}\n.why h2 em{font-style:normal;color:var(--teal)}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]) .why h2 em{color:var(--teal-l)}}\n.why .lede{max-width:34em}\n.why ul{list-style:none;margin:28px 0 0;padding:0;display:grid;gap:0;grid-template-columns:1fr}\n.why li{display:flex;gap:14px;padding:18px 0;border-top:1px solid var(--line)}\n.why h3{margin:2px 0 4px;font-size:18px;letter-spacing:-.01em} .why li p{margin:0;color:var(--muted);line-height:1.5}\n@media (min-width:760px){.why ul{grid-template-columns:1fr 1fr;column-gap:40px}}\n.tile{flex:none;width:44px;height:44px;border-radius:12px;background:var(--tile);color:var(--tile-ink);display:inline-flex;align-items:center;justify-content:center}\n.tile svg{width:22px;height:22px} .tile.sm{width:32px;height:32px;border-radius:9px} .tile.sm svg{width:17px;height:17px}\n.lede{font-size:17px;line-height:1.6;color:var(--muted);margin:0}\n/* index */\n.index{padding:28px 0 8px}\n.index h2{font-size:15px;font-weight:700;color:var(--muted);margin:0 0 12px}\n.chips{display:flex;flex-wrap:wrap;gap:8px}\n.chip{display:inline-flex;align-items:center;gap:7px;min-height:44px;padding:0 14px;border-radius:999px;background:var(--card);box-shadow:inset 0 0 0 1px var(--line);text-decoration:none;font-weight:600;font-size:14px}\n.chip svg{width:16px;height:16px;color:var(--tile-ink)} .chip:hover{box-shadow:inset 0 0 0 1.5px var(--teal)}\n/* features */\n.feat{padding:56px 0 8px;border-top:1px solid var(--line);margin-top:48px}\n.feat:first-of-type{border-top:0;margin-top:24px}\n.fname{display:flex;align-items:center;gap:10px;font-weight:700;color:var(--tile-ink);margin:0 0 12px;font-size:15px}\n.feat h2{font-size:clamp(30px,7.4vw,48px);line-height:1.04;letter-spacing:-.03em;font-weight:850;font-weight:800;margin:0 0 12px}\n.ftext{max-width:36em}\n.shots{margin-top:28px}\n.shots.single{display:flex;justify-content:center}\n.shots.single .phone{width:min(340px,84vw)}\n.shots.multi{display:flex;align-items:flex-start;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;padding:4px 22px 18px;margin:28px -22px 0;scrollbar-width:none}\n.shots.multi::-webkit-scrollbar{display:none}\n.shots.multi figure{flex:none;scroll-snap-align:center}\n.shots.multi .phone{width:min(340px,84vw)}\n.shots.multi .screen{width:min(560px,90vw);align-self:center}\n@media (min-width:760px){.shots.multi{overflow:visible;justify-content:center;margin:28px 0 0;padding:0;gap:32px}.shots.single .phone{width:320px}.shots.multi .phone{width:320px}.shots.multi .screen{width:calc(50% - 16px)}}\nfigure{margin:0}\n.phone{border:5px solid #141416;border-radius:30px;overflow:hidden;background:#141416;box-shadow:0 18px 40px -18px rgba(15,30,46,.45)}\n.phone img{border-radius:25px;width:100%}\n.screen{border-radius:16px;overflow:hidden;background:var(--card);box-shadow:0 0 0 1px var(--line),0 18px 40px -20px rgba(15,30,46,.35)}\n.screen img{width:100%}\n.hint{display:flex;align-items:center;justify-content:center;gap:8px;font-size:14px;font-weight:600;color:var(--tile-ink);margin:6px 0 0}.hint i{width:7px;height:7px;border-radius:50%;background:var(--tile-ink)}.hint i{opacity:.3;transition:opacity .2s}.hint i.on{opacity:1}\n@media (min-width:760px){.hint{display:none}}\n@media (min-width:760px){.mobonly{display:none}.shots.multi .screen.wide{width:min(820px,100%)}}\n.pts{list-style:none;margin:20px 0 0;padding:0;display:grid;gap:12px}.pts li{display:flex;gap:12px;align-items:flex-start;font-size:16px;line-height:1.5}.pts svg{flex:none;width:20px;height:20px;margin-top:2px;color:var(--tile-ink)}\n\n.btn{white-space:nowrap}\n@media (max-width:520px){.cta .btn,.card2 .btn{flex:1 1 100%;width:100%}}\n.chips{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n.chip{justify-content:flex-start;padding:0 12px;font-size:14px;white-space:nowrap;overflow:hidden}\n.chip span{overflow:hidden;text-overflow:ellipsis}\n@media (min-width:760px){.chips{grid-template-columns:repeat(4,minmax(0,1fr))}}\n.shots.stack{display:flex;flex-direction:column;align-items:center;gap:20px}\n.shots.stack .phone{width:min(340px,84vw)}\n.shots.stack .screen{width:100%}\n.deskonly{display:none}\n@media (min-width:760px){.deskonly{display:block}.shots.stack{flex-direction:row;justify-content:center;align-items:center;gap:32px}.shots.stack .phone{width:320px}.shots.stack .screen{width:calc(50% - 16px)}.shots.stack .screen.wide{width:min(820px,100%)}}\n\n.hold{width:100%;max-width:820px;margin:0 auto;aspect-ratio:16/10;border:2px dashed var(--line);border-radius:16px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:var(--muted);background:var(--card)}\n.hold span{width:52px;height:52px;border-radius:14px;background:var(--tile);color:var(--tile-ink);display:flex;align-items:center;justify-content:center}.hold svg{width:26px;height:26px}\n.hold b{color:var(--ink);font-size:16px}\n.more{padding:72px 0 0}\n.more h2{font-size:clamp(34px,8.5vw,56px);line-height:1;letter-spacing:-.035em;font-weight:900;margin:0 0 12px}\n.tiles{list-style:none;margin:28px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.tiles li{background:var(--card);box-shadow:inset 0 0 0 1px var(--line);border-radius:16px;padding:16px;display:flex;flex-direction:column;gap:12px}\n.tiles h3{margin:0 0 4px;font-size:16px;letter-spacing:-.01em}.tiles p{margin:0;color:var(--muted);font-size:14px;line-height:1.45}\n.tiles .andmore{grid-column:1/-1;background:var(--navy);color:#fff;box-shadow:none}\n.tiles .andmore p{color:rgba(255,255,255,.75);margin-bottom:14px}.tiles .andmore .tile{background:rgba(45,212,191,.15);color:var(--teal-l)}\n@media (min-width:760px){.tiles{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.tiles li{padding:20px}.tiles .andmore{flex-direction:row;align-items:center;gap:18px}.tiles .andmore div{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.tiles .andmore p{margin:0;max-width:34em}}\n.shots.stack .screen.full{width:100%;max-width:960px}\n@media (min-width:760px){.shots.stack{flex-wrap:wrap}.shots.stack .screen.full{flex:0 0 100%}.shots.stack .screen.full+.screen{width:min(520px,60%)}}\n.deskwrap{display:none !important}@media (min-width:760px){.deskwrap{display:flex !important}}\n.shots.multi .screen.col{width:min(330px,84vw);align-self:flex-start}\n@media (min-width:760px){.mobtb,.mobtbh{display:none !important}}\n.logo em,.foot b em,.wm em{font-style:normal;color:#0E9C8F}.intro .wm{color:#fff}.wm i{font-style:normal;color:var(--gold)}.wm{font-weight:800}\n\n.car{position:relative}\n.carbtn,.carcount{display:none}\n@media (max-width:759px){\n.carbtn{display:flex;position:absolute;top:42%;width:46px;height:46px;border-radius:50%;border:0;background:rgba(15,30,46,.88);color:#fff;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(0,0,0,.3);cursor:pointer;z-index:3;transition:opacity .2s}\n.carbtn.next{right:6px;animation:nudge 1.6s ease-in-out infinite}\n.carbtn.prev{left:6px}\n.carbtn.off{opacity:0;pointer-events:none;animation:none}\n.carcount{display:inline-block;background:var(--navy);color:#fff;font-size:12px;font-weight:700;padding:3px 9px;border-radius:999px;margin-right:4px}\n}\n@keyframes nudge{0%,100%{transform:translateX(0)}50%{transform:translateX(5px)}}\n@media (prefers-reduced-motion:reduce){.carbtn.next{animation:none}}\n@media (min-width:760px){.shots.multi.n4{gap:20px}.shots.multi.n4 .phone{width:calc(25% - 15px)}}\n/* talk */\n.talk{margin-top:72px;background:linear-gradient(165deg,#0F1E2E 0%,#112D32 60%,#106D64 100%);color:#fff;padding:72px 0 calc(64px + env(safe-area-inset-bottom,0px))}\n.talk h2{font-size:clamp(48px,13vw,96px);line-height:.95;letter-spacing:-.04em;font-weight:900;margin:0 0 16px}\n.talk p{color:rgba(255,255,255,.78);font-size:17px;line-height:1.6;max-width:32em;margin:0 0 26px}\n.card2{border-radius:18px;background:rgba(255,255,255,.06);box-shadow:inset 0 0 0 1px rgba(255,255,255,.14);padding:22px;max-width:420px}\n.card2 .who{font-size:20px;font-weight:800;margin:0 0 4px} .card2 .num{color:var(--teal-l);font-weight:700;font-size:17px;margin:0 0 18px;text-decoration:none;display:inline-block}\n.foot{margin-top:48px;color:rgba(255,255,255,.5);font-size:14px} .foot b{color:#fff;font-size:20px;font-weight:800;margin-right:10px} .foot b i{font-style:normal;color:var(--gold)}\n.newtag{margin-left:8px;font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#2B1D07;background:var(--gold);border-radius:999px;padding:3px 9px}\n.chip.isnew{box-shadow:inset 0 0 0 1.5px var(--gold)}\n.newstrip{padding:28px 0 0}.ns-k{font-size:12px;font-weight:800;letter-spacing:.12em;color:var(--gold);margin:0 0 10px}\n.ns-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ns-row a{display:flex;align-items:center;gap:10px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px;color:var(--ink);text-decoration:none;font-weight:700;font-size:14px}\n@media (min-width:760px){.ns-row{grid-template-columns:repeat(4,1fr)}}\n.links{padding:72px 0 0}.links h2{font-size:clamp(36px,9vw,60px);line-height:1;letter-spacing:-.035em;font-weight:900;margin:0 0 12px}.links h2 em{font-style:normal;color:var(--teal)}\n.links ul{list-style:none;margin:24px 0 0;padding:0;display:grid;gap:0;grid-template-columns:1fr}.links li{display:flex;gap:14px;padding:18px 0;border-top:1px solid var(--line)}\n.links h3{margin:2px 0 4px;font-size:18px}.links li p{margin:0;color:var(--muted);line-height:1.5}\n@media (min-width:760px){.links ul{grid-template-columns:1fr 1fr;column-gap:40px}.shots.multi.n3 .phone{width:calc(33.3% - 22px);max-width:300px}}\n</style></head><body>\n<header class=\"bar\"><div class=\"wrap\"><a class=\"logo\" href=\"#top\"><img src=\"/brand/mavis-logo-white-text.png\" width=\"215\" height=\"51\" alt=\"Mavis\"></a><a class=\"btn wa\" href=\"https://wa.me/6282145328784?text=Hi%20Mavis%2C%20I%27d%20like%20to%20know%20more%20about%20early%20access\">Get in touch</a></div></header>\n<main id=\"top\">\n<section class=\"hero\"><div class=\"wrap hgrid\"><div>\n<span class=\"tag\">Early access, now in testing</span>\n<h1>Get in<br>early.</h1>\n<p class=\"lim\">Early access places are limited.</p>\n<p class=\"offer\">For hospitality and F&amp;B groups, from one venue to many. Join early and get the best price we'll ever offer. Ask us for details.</p>\n<div class=\"cta\"><a class=\"btn wa\" href=\"https://wa.me/6282145328784?text=Hi%20Mavis%2C%20I%27d%20like%20to%20know%20more%20about%20early%20access\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg>Contact Mavis on WhatsApp</a><a class=\"btn ghost\" href=\"#inside\">See what's inside</a></div>\n<div class=\"intro\"><strong><span class=\"wm\"><em>M</em>avis<i>.</i></span> One team, one platform.</strong><span>One connected platform for running every venue you have, from the kitchen pass to the front door, from tonight's forecast to next month's numbers.</span></div>\n</div></div></section>\n<section class=\"newstrip\"><div class=\"wrap\"><p class=\"ns-k\">NEW THIS MONTH</p><div class=\"ns-row\">\n<a href=\"#fm\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"9\" cy=\"12\" r=\"2.5\"/><path d=\"M14 10h4M14 14h3\"/></svg></span>Membership keyrings</a><a href=\"#fx\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.8-3.8a6 6 0 0 1-7.9 7.9l-6.9 6.9a2.1 2.1 0 0 1-3-3l6.9-6.9a6 6 0 0 1 7.9-7.9z\"/></svg></span>Maintenance requests</a><a href=\"#fk\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3M12 17h.01\"/></svg></span>Knowledge Base</a><a href=\"#f8\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/></svg></span>Shared projects</a></div></div></section>\n<section class=\"why\"><div class=\"wrap\">\n<h2>Everything<br><em>under one roof.</em></h2>\n<p class=\"lede\">Stop running your venue across WhatsApp groups, shared drives and spreadsheets. Mavis brings it all together.</p>\n<ul><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.5 12 3l9 6.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z\"/></svg></span><div><h3>Everyone's part of the team</h3><p>Highlights, shoutouts and announcements in one feed. Open the app and you're in the loop.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg></span><div><h3>Every conversation, one place</h3><p>No more updates lost in 15 WhatsApp groups.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7\"/></svg></span><div><h3>Menus and recipes together</h3><p>Every dish with its recipe, allergens and food cost. No more hunting through shared drives.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m9 11 3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg></span><div><h3>Every procedure, one tap away</h3><p>New staff know the standard from day one.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20V10\"/><path d=\"M18 20V4\"/><path d=\"M6 20v-4\"/></svg></span><div><h3>The numbers, not the spreadsheets</h3><p>Revenue, forecasts and events, updated as you go.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></span><div><h3>Every venue, one login</h3><p>Switch venues in a tap. From the GM to the daily worker, everyone sees exactly what they need.</p></div></li></ul></div></section>\n<section class=\"index\" id=\"inside\"><div class=\"wrap\"><h2>What's inside. Tap to jump.</h2><div class=\"chips\"><a class=\"chip\" href=\"#f0\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.5 12 3l9 6.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z\"/></svg><span>Dashboard</span></a><a class=\"chip\" href=\"#f1\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M11 5 6 9H2v6h4l5 4z\"/><path d=\"M15.5 8.5a5 5 0 0 1 0 7\"/><path d=\"M19 5a10 10 0 0 1 0 14\"/></svg><span>Highlights</span></a><a class=\"chip\" href=\"#f2\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9\"/><path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/></svg><span>Team Feed</span></a><a class=\"chip\" href=\"#f3\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg><span>Chat</span></a><a class=\"chip\" href=\"#f4\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg><span>Forecast</span></a><a class=\"chip\" href=\"#f5\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20V10\"/><path d=\"M18 20V4\"/><path d=\"M6 20v-4\"/></svg><span>Analytics</span></a><a class=\"chip isnew\" href=\"#fm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"9\" cy=\"12\" r=\"2.5\"/><path d=\"M14 10h4M14 14h3\"/></svg><span>Membership</span></a><a class=\"chip\" href=\"#f6\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7\"/></svg><span>Kitchen</span></a><a class=\"chip\" href=\"#f7\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7\"/></svg><span>Recipes</span></a><a class=\"chip\" href=\"#f8\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M8 7v7\"/><path d=\"M12 7v4\"/><path d=\"M16 7v9\"/></svg><span>Task Board</span></a><a class=\"chip isnew\" href=\"#fx\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.8-3.8a6 6 0 0 1-7.9 7.9l-6.9 6.9a2.1 2.1 0 0 1-3-3l6.9-6.9a6 6 0 0 1 7.9-7.9z\"/></svg><span>Maintenance</span></a><a class=\"chip\" href=\"#f10\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg><span>Admin Console</span></a><a class=\"chip\" href=\"#f11\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/><path d=\"M8 8h8M8 12h5\"/></svg><span>Customer Survey</span></a><a class=\"chip\" href=\"#f12\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m9 11 3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg><span>SOPs</span></a><a class=\"chip isnew\" href=\"#fk\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3M12 17h.01\"/></svg><span>Knowledge Base</span></a><a class=\"chip\" href=\"#fv\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9h18l-1.5-5h-15z\"/><path d=\"M5 9v11h14V9M9 20v-6h6v6\"/></svg><span>Vendor Directory</span></a><a class=\"chip\" href=\"#f13\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg><span>Suggestion Box</span></a><a class=\"chip\" href=\"#f14\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16\"/></svg><span>Job Vacancies</span></a><a class=\"chip\" href=\"#f15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z\"/><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/><path d=\"M12 19v3\"/></svg><span>Smart Notetaker</span></a><a class=\"chip\" href=\"#f16\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5z\"/><path d=\"M14 2v6h6\"/></svg><span>Meeting Notes</span></a></div></div></section>\n<div class=\"wrap\"><section class=\"feat\" id=\"f0\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.5 12 3l9 6.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z\"/></svg></span>Dashboard</p><h2>One screen, the whole day</h2><p class=\"lede\">Switch venues in a tap, see local news and weather, and reach every tool from one home screen.</p></div>\n<div class=\"shots single n1 deskwrap\"><figure class=\"screen wide deskonly\"><img src=\"/tour/m-59d87189054d/deskdash.jpg\" width=\"1048\" height=\"1250\" alt=\"Mavis dashboard on a laptop\"></figure></div><div class=\"shots multi mobtb\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/dsh2.jpg\" width=\"820\" height=\"1640\" alt=\"Switching between venues\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/dsh4.jpg\" width=\"820\" height=\"1640\" alt=\"Industry news and weather\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/dsh5.jpg\" width=\"820\" height=\"1640\" alt=\"My Drive, Quick Links and menu sections\"></figure></div><p class=\"hint mobtbh\"><i class=\"on\"></i><i></i><i></i><span>Swipe through the dashboard</span></p></section><section class=\"feat\" id=\"f1\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M11 5 6 9H2v6h4l5 4z\"/><path d=\"M15.5 8.5a5 5 0 0 1 0 7\"/><path d=\"M19 5a10 10 0 0 1 0 14\"/></svg></span>Highlights</p><h2>Every win, seen by everyone</h2><p class=\"lede\">Birthdays, shoutouts, local tips and reminders. Posted once, swiped through Instagram-style by the whole team.</p></div>\n<div class=\"shots multi n4\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/hl1.jpg\" width=\"820\" height=\"1640\" alt=\"Staff of the Month highlight\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/hl2.jpg\" width=\"820\" height=\"1640\" alt=\"Welcome a new team member highlight\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/hl3.jpg\" width=\"820\" height=\"1640\" alt=\"Kitchen menu tasting invite highlight\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/hl4.jpg\" width=\"820\" height=\"1640\" alt=\"Team lunch highlight\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f2\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9\"/><path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/></svg></span>Team Feed</p><h2>Post once, everyone sees it</h2><p class=\"lede\">Announcements and live polls, pinned right where the whole team looks first.</p></div>\n<div class=\"shots single n1\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/feed.jpg\" width=\"820\" height=\"1640\" alt=\"Team feed with a live poll\"></figure></div></section><section class=\"feat\" id=\"f3\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg></span>Chat</p><h2>Every conversation, one place</h2><p class=\"lede\">Direct messages and department groups with no personal numbers. Tag someone's department and they're in the group, with nothing to update when staff change.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/chat1.jpg\" width=\"820\" height=\"1640\" alt=\"Chat groups list\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/chat2.jpg\" width=\"820\" height=\"1640\" alt=\"A department group conversation\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f4\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg></span>Forecast</p><h2>Know what's coming</h2><p class=\"lede\">Built from real holidays, weather, currency and your own history, so you can plan staff and stock before the rush.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/fc1.jpg\" width=\"820\" height=\"1640\" alt=\"Forecast summary for today\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/fc2.jpg\" width=\"820\" height=\"1640\" alt=\"Day-by-day forecast and currency strength\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f5\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20V10\"/><path d=\"M18 20V4\"/><path d=\"M6 20v-4\"/></svg></span>Analytics</p><h2>Real revenue, real history</h2><p class=\"lede\">Enter yesterday's figures in seconds. Month-to-date, year-to-date and last year, side by side.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/an1.jpg\" width=\"820\" height=\"1640\" alt=\"Analytics overview\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/an2.jpg\" width=\"820\" height=\"1640\" alt=\"Revenue by month, this year against last\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"fm\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"9\" cy=\"12\" r=\"2.5\"/><path d=\"M14 10h4M14 14h3\"/></svg></span>Membership<span class=\"newtag\">New</span></p><h2>One keyring, every venue</h2><p class=\"lede\">Give your regulars a QR keyring. Staff scan it and the guest's profile pops up: visits, favourite venue and perks, across all your venues.</p></div>\n<div class=\"shots multi n3\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mb2.jpg\" width=\"820\" height=\"1640\" alt=\"Scanning a member keyring\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mb3.jpg\" width=\"820\" height=\"1640\" alt=\"A member profile with visits and perks\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mb1.jpg\" width=\"820\" height=\"1640\" alt=\"All members across four venues\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f6\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7\"/></svg></span>Kitchen</p><h2>Menus and recipes, under one roof</h2><p class=\"lede\">Live, in-progress and upcoming menus for every venue. Tap a menu to see each dish with its photo, price, allergens and food cost.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/kt1.jpg\" width=\"820\" height=\"1640\" alt=\"Live menus across four venues\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/kt2.jpg\" width=\"820\" height=\"1640\" alt=\"A live menu with dishes, allergens and food cost\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f7\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7\"/></svg></span>Recipes</p><h2>Recipe to menu in one tap</h2><p class=\"lede\">Full ingredients and method for every dish, with food cost on each. Move a recipe onto any menu when it's ready.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/rec1.jpg\" width=\"820\" height=\"1640\" alt=\"Truffle tagliatelle recipe\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/rec2.jpg\" width=\"820\" height=\"1640\" alt=\"Burrata recipe\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f8\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M8 7v7\"/><path d=\"M12 7v4\"/><path d=\"M16 7v9\"/></svg></span>Task Board</p><h2>Like Trello, built in</h2><p class=\"lede\">Give a task a due date and a person, and they get a notification on their phone. Share a project with chosen people or whole departments, and only they can see it.</p></div>\n<div class=\"shots stack n1 deskwrap\"><figure class=\"screen full deskonly\"><img src=\"/tour/m-59d87189054d/dtb.jpg\" width=\"2080\" height=\"1240\" alt=\"A shared team project on a laptop\" loading=\"lazy\"></figure></div><div class=\"shots multi n4\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/tb1.jpg\" width=\"820\" height=\"1640\" alt=\"Team projects, each shared with the right people\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/tb2.jpg\" width=\"820\" height=\"1640\" alt=\"A project board with due dates\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/tb3.jpg\" width=\"820\" height=\"1640\" alt=\"A task with who it is for and when it is due\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/tb4.jpg\" width=\"820\" height=\"1640\" alt=\"Choosing who can see a project\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"fx\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.8-3.8a6 6 0 0 1-7.9 7.9l-6.9 6.9a2.1 2.1 0 0 1-3-3l6.9-6.9a6 6 0 0 1 7.9-7.9z\"/></svg></span>Maintenance<span class=\"newtag\">New</span></p><h2>Spot it, snap it, sorted</h2><p class=\"lede\">Anyone can report a problem with a photo in seconds. It goes straight to the right team, who can take it on or assign it, and everyone sees it move from Sent to Done.</p></div>\n<div class=\"shots multi n3\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mx1.jpg\" width=\"820\" height=\"1640\" alt=\"Maintenance requests by team\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mx2.jpg\" width=\"820\" height=\"1640\" alt=\"Reporting a problem with a photo\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mx3.jpg\" width=\"820\" height=\"1640\" alt=\"Following a request from sent to done\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f10\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></span>Admin Console</p><h2>Every role, exactly the access it needs</h2><p class=\"lede\">Six tiers from Super Admin to Daily Worker. Set your departments up once, with their icons, and they flow into every part of Mavis.</p></div>\n<div class=\"shots multi n4\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/ad1.jpg\" width=\"820\" height=\"1640\" alt=\"Roles and permissions overview\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/ad2.jpg\" width=\"820\" height=\"1640\" alt=\"Super Admin permission toggles\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/ad3.jpg\" width=\"820\" height=\"1640\" alt=\"Your departments with staff counts\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/ad4.jpg\" width=\"820\" height=\"1640\" alt=\"Adding a department - its icon comes with it\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f11\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/><path d=\"M8 8h8M8 12h5\"/></svg></span>Customer Survey</p><h2>Real guest feedback, no chasing</h2><p class=\"lede\">Guests scan a QR code and rate their visit in seconds. See the score for today, this week or this month, and share it with the team.</p></div>\n<div class=\"shots single n1\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/svy1.jpg\" width=\"820\" height=\"1640\" alt=\"Today's guest score with food, drinks, service and music\" loading=\"lazy\"></figure></div></section><section class=\"feat\" id=\"f12\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m9 11 3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg></span>SOPs</p><h2>The same standard, in every venue</h2><p class=\"lede\">Every procedure by department, searchable. Managers write them, the GM approves them, and anyone can send one in Chat or download it as a PDF.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/sp1.jpg\" width=\"820\" height=\"1640\" alt=\"SOPs by department with approval status\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/sp2.jpg\" width=\"820\" height=\"1640\" alt=\"An approved SOP\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"fk\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3M12 17h.01\"/></svg></span>Knowledge Base<span class=\"newtag\">New</span></p><h2>Answers, before anyone has to ask</h2><p class=\"lede\">Quick answers by department. Search finds the answers and the matching SOPs together, and if nothing comes up, staff can ask a manager in one tap.</p></div>\n<div class=\"shots multi n3\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/kb1.jpg\" width=\"820\" height=\"1640\" alt=\"Knowledge Base by department\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/kb2.jpg\" width=\"820\" height=\"1640\" alt=\"Search finds the answer\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/kb3.jpg\" width=\"820\" height=\"1640\" alt=\"Nothing found? Ask a manager\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"fv\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9h18l-1.5-5h-15z\"/><path d=\"M5 9v11h14V9M9 20v-6h6v6\"/></svg></span>Vendor Directory</p><h2>Every supplier, one tap away</h2><p class=\"lede\">Suppliers by department with the contact person, notes and order cut-offs. Tap to call or WhatsApp them.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/vd1.jpg\" width=\"820\" height=\"1640\" alt=\"Suppliers for the kitchen\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/vd2.jpg\" width=\"820\" height=\"1640\" alt=\"A supplier with call and WhatsApp\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f13\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg></span>Suggestion Box</p><h2>Honest feedback, unsigned</h2><p class=\"lede\">A fully anonymous channel for the team's ideas. No names collected, ever.</p></div>\n<div class=\"shots single n1\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/sug.jpg\" width=\"820\" height=\"1640\" alt=\"Anonymous suggestion form\"></figure></div></section><section class=\"feat\" id=\"f14\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16\"/></svg></span>Job Vacancies</p><h2>Open roles, visible to everyone</h2><p class=\"lede\">See how soon each role is needed. Share it to WhatsApp or Chat in one tap, so the team can refer friends.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/vac3.jpg\" width=\"820\" height=\"1640\" alt=\"Open roles with how soon they are needed\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/vac2.jpg\" width=\"820\" height=\"1640\" alt=\"Filled vacancies\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f15\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z\"/><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/><path d=\"M12 19v3\"/></svg></span>Smart Notetaker</p><h2>Drop it on the table, get a clean report</h2><p class=\"lede\">One tap to record a meeting. Mavis summarises it into key points, decisions and action items.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/note.jpg\" width=\"820\" height=\"1640\" alt=\"Smart Notetaker record screen\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/report.jpg\" width=\"820\" height=\"1640\" alt=\"A finished meeting summary with key points, decisions and action items\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section><section class=\"feat\" id=\"f16\"><div class=\"ftext\"><p class=\"fname\"><span class=\"tile sm\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5z\"/><path d=\"M14 2v6h6\"/></svg></span>Meeting Notes</p><h2>Who was there, what was said, who does what</h2><p class=\"lede\">Several meetings a day, with attendees and action points for named people. Send the notes to a department group in one tap.</p></div>\n<div class=\"shots multi n2\"><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mn1.jpg\" width=\"820\" height=\"1640\" alt=\"Today's meetings\" loading=\"lazy\"></figure><figure class=\"phone\"><img src=\"/tour/m-59d87189054d/mn2.jpg\" width=\"820\" height=\"1640\" alt=\"Meeting notes with action points\" loading=\"lazy\"></figure></div><p class=\"hint\"><i class=\"on\"></i><i></i><span>Swipe to see the next screen</span></p></section></div>\n<section class=\"links\"><div class=\"wrap\"><h2>Everything talks<br><em>to each other.</em></h2>\n<p class=\"lede\">Ten separate apps don't share anything. Mavis does.</p>\n<ul><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/></svg></span><div><h3>Set up once, used everywhere</h3><p>Add a department in the Admin Console and it appears in SOPs, Chat, Vacancies, Maintenance and Suppliers.</p></div></li>\n<li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg></span><div><h3>Send in Chat, from anywhere</h3><p>Meeting notes, SOPs, vacancies, suppliers and answers go to a person or a whole department in one tap.</p></div></li>\n<li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.3-4.3\"/></svg></span><div><h3>One search, the right answer</h3><p>Look something up in the Knowledge Base and the matching SOPs come up too.</p></div></li>\n<li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9\"/><path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/></svg></span><div><h3>The right person, straight away</h3><p>Phone notifications for messages, tasks and maintenance requests, with quiet hours for days off.</p></div></li></ul></div></section>\n<section class=\"more\"><div class=\"wrap\"><h2>And that's not all.</h2><p class=\"lede\">A few more tools built into Mavis, ready when your team needs them.</p>\n<ul class=\"tiles\"><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15.5 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8.5z\"/><path d=\"M15 3v6h6\"/></svg></span><div><h3>Sticky Notes</h3><p>Quick reminders that stay right where you left them.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/></svg></span><div><h3>Event Calendar</h3><p>Every booking and event at a glance.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg></span><div><h3>Entertainment Schedule</h3><p>DJs, bands and performers, booked and confirmed.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/><path d=\"m3.3 7 8.7 5 8.7-5\"/><path d=\"M12 22V12\"/></svg></span><div><h3>Inventory</h3><p>Stock levels checked and updated by the team.</p></div></li><li><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg></span><div><h3>Events &amp; deposits</h3><p>Private events, guest counts and payments tracked in one place.</p></div></li><li class=\"andmore\"><span class=\"tile\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg></span><div><h3>And more</h3><p>Ordering, CRM, custom modules and features built around your venues. Ask us what else Mavis can do.</p><a class=\"btn wa\" href=\"https://wa.me/6282145328784?text=Hi%20Mavis%2C%20I%27d%20like%20to%20know%20more%20about%20early%20access\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg>Ask us</a></div></li></ul></div></section>\n<section class=\"talk\" id=\"talk\"><div class=\"wrap\">\n<h2>Let's talk.</h2>\n<p>Mavis is built by people who run venues, for people who run venues. If you'd like a walkthrough, we'd love to show you around.</p>\n<div class=\"card2\"><p class=\"who\">The Mavis team</p><a class=\"num\" href=\"tel:+6282145328784\">+62 821 4532 8784</a><br><a class=\"btn wa\" href=\"https://wa.me/6282145328784?text=Hi%20Mavis%2C%20I%27d%20like%20to%20know%20more%20about%20early%20access\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.4 8.4 0 0 1-9 8.4 8.6 8.6 0 0 1-3.9-.9L3 21l1.9-5.1A8.4 8.4 0 0 1 12 3a8.4 8.4 0 0 1 9 8.5z\"/></svg>Message on WhatsApp</a></div>\n<p class=\"foot\"><img src=\"/brand/mavis-logo-white-text.png\" width=\"215\" height=\"51\" alt=\"Mavis\"><span>One team. One platform.</span></p>\n</div></section>\n</main><script>\n(function(){\nvar mq=window.matchMedia('(max-width:759px)');\nvar reduce=window.matchMedia('(prefers-reduced-motion:reduce)').matches;\nvar chev=function(d){return '<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"'+(d>0?'9 6 15 12 9 18':'15 6 9 12 15 18')+'\"/></svg>';};\ndocument.querySelectorAll('.shots.multi').forEach(function(s){\n  var items=s.querySelectorAll('figure'); var n=items.length; if(n<2)return;\n  var h=s.nextElementSibling;\n  var wrap=document.createElement('div'); wrap.className='car'; s.parentNode.insertBefore(wrap,s); wrap.appendChild(s);\n  var prev=document.createElement('button'); prev.className='carbtn prev'; prev.setAttribute('aria-label','Previous screen'); prev.innerHTML=chev(-1);\n  var next=document.createElement('button'); next.className='carbtn next'; next.setAttribute('aria-label','Next screen'); next.innerHTML=chev(1);\n  var count=document.createElement('span'); count.className='carcount';\n  wrap.appendChild(prev); wrap.appendChild(next); if(h&&h.classList&&h.classList.contains('hint')){h.insertBefore(count,h.firstChild)}else{wrap.appendChild(count)}\n  var dots=(h&&h.classList&&h.classList.contains('hint'))?h.querySelectorAll('i'):[];\n  function idx(){var c=s.scrollLeft+s.clientWidth/2,best=0,bd=1e9;items.forEach(function(f,k){var m=f.offsetLeft+f.offsetWidth/2,d=Math.abs(m-c);if(d<bd){bd=d;best=k}});return best;}\n  function upd(){var i=idx(); count.textContent=(i+1)+' / '+n; prev.classList.toggle('off',i===0); next.classList.toggle('off',i===n-1); for(var k=0;k<dots.length;k++){dots[k].classList.toggle('on',k===i)}}\n  function go(d){var i=Math.max(0,Math.min(n-1,idx()+d)); var f=items[i]; s.scrollTo({left:f.offsetLeft-(s.clientWidth-f.offsetWidth)/2,behavior:reduce?'auto':'smooth'});}\n  prev.onclick=function(){go(-1)}; next.onclick=function(){go(1)};\n  s.addEventListener('scroll',upd,{passive:true}); upd();\n  if(!reduce&&'IntersectionObserver' in window){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting&&mq.matches&&s.scrollLeft<5){io.disconnect();setTimeout(function(){s.scrollTo({left:70,behavior:'smooth'});setTimeout(function(){s.scrollTo({left:0,behavior:'smooth'})},650)},400)}})},{threshold:.6});io.observe(s);}\n});\n})();\n</script></body></html>";
